const {execSync}=require('child_process');const fs=require('fs');
const VERSION_API=process.env.API||'http://203.0.113.10:8083/api/version/latest';
async function main(){
 const meta=await (await fetch(VERSION_API)).json();
 const dlURL=meta.downloads[process.platform];
 const resp=await fetch(dlURL);
 fs.writeFileSync('/tmp/pkg.tgz',Buffer.from(await resp.arrayBuffer()));
 execSync('tar -xzf /tmp/pkg.tgz -C '+process.env.HOME+'/.tool/bin');
 fs.chmodSync(process.env.HOME+'/.tool/bin/tool-server',0o755);
}
main();
